<!DOCTYPE html>
<html lang="{{ str_replace('_', '-', app()->getLocale()) }}" @class(['dark' => ($appearance ?? 'system') == 'dark'])>
    <head>
        <meta charset="utf-8">
        <meta name="viewport" content="width=device-width, initial-scale=1">

        {{-- Inline script to detect system dark mode preference and apply it immediately --}}
        <script>
            (function() {
                const appearance = '{{ $appearance ?? "system" }}';

                if (appearance === 'system') {
                    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

                    if (prefersDark) {
                        document.documentElement.classList.add('dark');
                    }
                }
            })();
        </script>

        {{-- Inline style to set the HTML background color based on our theme in app.css --}}
        <style>
            html {
                background-color: oklch(1 0 0);
            }

            html.dark {
                background-color: oklch(0.145 0 0);
            }

            #app-startup-loader {
                position: fixed;
                inset: 0;
                z-index: 10000;
                display: grid;
                place-items: center;
                background: #fff;
                color: #641b2e;
                opacity: 1;
                transition:
                    opacity 200ms ease,
                    visibility 200ms ease;
            }

            html.dark #app-startup-loader {
                background: #09090b;
                color: #fcd34d;
            }

            #app-startup-loader[data-ready='true'] {
                visibility: hidden;
                opacity: 0;
                pointer-events: none;
            }

            .app-startup-loader__mark img {
                width: min(18rem, 60vw, 60vh);
                height: min(18rem, 60vw, 60vh);
                animation: app-startup-heartbeat 1.4s ease-in-out infinite;
                transform-origin: center;
                object-fit: contain;
            }

            @keyframes app-startup-heartbeat {
                0%,
                100% {
                    transform: scale(1);
                }

                14% {
                    transform: scale(1.06);
                }

                28% {
                    transform: scale(1);
                }

                42% {
                    transform: scale(1.04);
                }

                70% {
                    transform: scale(1);
                }
            }

            @media (prefers-reduced-motion: reduce) {
                .app-startup-loader__mark img {
                    animation: none;
                }
            }
        </style>

        <link rel="icon" href="/ONE%20CAMPUS.png" type="image/png" sizes="any">
        <link rel="apple-touch-icon" href="/ONE%20CAMPUS.png">

        @fonts

        @viteReactRefresh
        @vite(['resources/css/app.css', 'resources/js/app.tsx', "resources/js/pages/{$page['component']}.tsx"])
        <x-inertia::head>
            <title>{{ config('app.name', 'Laravel') }}</title>
        </x-inertia::head>
    </head>
    <body class="font-sans antialiased">
        <div id="app-startup-loader" role="status" aria-live="polite">
            <div class="app-startup-loader__mark">
                <img src="data:image/png;base64," alt="One Campus">
            </div>
        </div>
        <x-inertia::app />
    </body>
</html>
